// Transports the backend's generated documentation into this site.
//
// Five tables are generated by the backend, one directory up, and must never be
// retyped here:
//
//   docs/admin-routes.md             → reference/admin-api.mdx (controller decorators)
//   packages/client/COMPATIBILITY.md → reference/sdk.mdx       (SDK contract tests)
//   docs/cli-commands.md             → cli/commands.mdx        (the command registry)
//   docs/cli-commands.md             → cli/overview.mdx        (the same, one row per command)
//   docs/settings.md                 → reference/settings.mdx  (the settings registry)
//
// All four had been maintained by hand on this side. The route table had drifted
// badly — the controllers that mount on a HTTP_ROUTES constant were documented
// with their unresolved paths, so every path copied out of the docs 404'd — and
// the compatibility matrix drifted the other way: it called `client.schema()`
// "not in this SDK" while the contract test asserts it calls functions in
// another schema, and it promised `createSignedUrl` honoured `expiresIn` while
// the test records that the driver decides the lifetime.
//
// The CLI reference drifted the first way too, and worse: thirteen command groups
// existed in `motherbase --help` and not in the page. The settings reference opened
// with "Generated from the settings registry" and was six groups short.
//
// The backend owns every extraction, each guarded by its own test
// (`apps/server/tests/route-manifest.unit.test.ts`,
// `apps/server/tests/sdk-contract.integration.test.ts`,
// `packages/cli/test/docs.test.js`,
// `apps/server/tests/settings-docs.unit.test.ts`). This script only
// transports the result, so the site and the code cannot disagree about what was
// generated.
//
//   npm run docs:sync
//
// Exits 1 when a generated file is missing, rather than silently leaving a stale
// table behind: a sync that quietly does nothing is how this drifted originally.
//
// `lib/__tests__/sync-backend-docs.test.ts` imports the exports below and fails
// when a committed table no longer matches the backend's.
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';

const REPO_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..');

/** The site lives in `website/` of the backend repository: the backend is its parent. */
export const BACKEND_DIR = path.resolve(REPO_ROOT, '..');

/**
 * Drop the generator's "do not edit" banner — each target page carries its own
 * — and the `# Title` the standalone file needs but a page section does not.
 */
const stripPreamble = source =>
  source
    .replace(/^<!--[\s\S]*?-->\n/, '')
    .replace(/^#\s+.*\n/m, '')
    .trim();

/**
 * Escape the two characters MDX reads as syntax rather than as prose.
 *
 * The backend's files are plain Markdown. `createClient<Database> types from()
 * and rpc()` and `--confirm <name>` are ordinary sentences there; spliced into
 * an `.mdx` page they are an opening JSX tag with no matching close. So is a
 * brace: `{ auth: { persistSession } }` is an object in the prose of the
 * compatibility matrix and a JSX expression once it is MDX, and acorn refuses
 * it with "Could not parse expression".
 *
 * Both failures land in the published site's build, which is the one gate
 * neither repository's test suite runs, so both are escaped here and asserted
 * on the spliced pages by `lib/__tests__/sync-backend-docs.test.ts`.
 *
 * Code spans are left alone: inside backticks MDX parses neither, and
 * `` `<name>` `` must keep its brackets.
 */
const MDX_SYNTAX = { '<': '&lt;', '>': '&gt;', '{': '&#123;', '}': '&#125;' };

export function escapeMdxSyntax(body) {
  // Split on code spans and fenced blocks, keeping them; escape only between.
  return body
    .split(/(```[\s\S]*?```|`[^`\n]*`)/g)
    .map((part, index) =>
      index % 2 === 1 ? part : part.replace(/[<>{}]/g, character => MDX_SYNTAX[character]),
    )
    .join('');
}

/**
 * Turn the compatibility matrix into the page's own shape.
 *
 * The standalone file is addressed to someone reading the repository: it opens
 * with a legend and totals, numbers its rows by test id and uses `##` headings.
 * On the page the legend lives in the prose above the markers, the test id is
 * noise for a reader who will never run the suite, and the section sits under a
 * `##` heading already.
 */
export function compatibilityTable(source) {
  const body = stripPreamble(source)
    // Everything before the first section heading is the legend and the totals.
    .replace(/^[\s\S]*?(?=^## )/m, '')
    .split('\n')
    // Demote the section headings one level, under the page's own `##`.
    .map(line => (line.startsWith('## ') ? `#${line}` : line))
    // Drop the leading `Test id` cell from the header, the separator and every row.
    .map(line => (line.startsWith('| ') ? line.replace(/^\|[^|]*\|/, '|') : line))
    .join('\n');

  return body.trim();
}

/**
 * The CLI overview: one row per top-level command, its description, and the
 * names of its subcommands, read off the command table. The overview used to
 * summarise the groups by hand and named a third of the subcommands.
 */
export function cliOverviewTable(source) {
  const rows = [...stripPreamble(source).matchAll(/^\| `([^`]+)` \| `motherbase[^`]*` \| (.*?) \|$/gm)];
  const commands = new Map();
  for (const [, name, description] of rows) {
    const [top, ...rest] = name.split(' ');
    if (!commands.has(top)) commands.set(top, { description: '', subcommands: [] });
    if (rest.length) commands.get(top).subcommands.push(rest.join(' '));
    else commands.get(top).description = description;
  }
  const lines = ['| Command | What it does | Subcommands |', '|---|---|---|'];
  for (const [top, { description, subcommands }] of commands) {
    const subs = subcommands.length ? subcommands.map(sub => `\`${sub}\``).join(', ') : '—';
    lines.push(`| \`${top}\` | ${description} | ${subs} |`);
  }
  return lines.join('\n');
}

/**
 * The generated blocks, in the order a reader meets them.
 *
 * `marker` names the pair of MDX comments that delimit the block; `transform`
 * is how the backend's file becomes the section's body.
 */
export const BLOCKS = [
  {
    marker: 'GENERATED ROUTES',
    source: 'docs/admin-routes.md',
    target: 'content/docs/reference/admin-api.mdx',
    transform: stripPreamble,
  },
  {
    marker: 'GENERATED COMPATIBILITY',
    source: 'packages/client/COMPATIBILITY.md',
    target: 'content/docs/reference/sdk.mdx',
    transform: compatibilityTable,
  },
  {
    marker: 'GENERATED CLI',
    source: 'docs/cli-commands.md',
    target: 'content/docs/cli/commands.mdx',
    transform: stripPreamble,
  },
  {
    marker: 'GENERATED CLI OVERVIEW',
    source: 'docs/cli-commands.md',
    target: 'content/docs/cli/overview.mdx',
    transform: cliOverviewTable,
  },
  {
    marker: 'GENERATED SETTINGS',
    source: 'docs/settings.md',
    target: 'content/docs/reference/settings.mdx',
    transform: stripPreamble,
  },
];

export const beginMarker = marker => `{/* BEGIN ${marker} */}`;
export const endMarker = marker => `{/* END ${marker} */}`;

/** Absolute path of a block's source inside a backend checkout. */
export const sourcePath = (block, backendDir) => path.join(backendDir, block.source);

/** Absolute path of a block's page in this repository. */
export const targetPath = block => path.join(REPO_ROOT, block.target);

/**
 * A block's source, transformed into the body the page should carry.
 *
 * Every block goes through `escapeMdxSyntax`, because every generator writes
 * plain Markdown and every target is MDX.
 */
export const generatedBody = (block, backendDir) =>
  escapeMdxSyntax(block.transform(fs.readFileSync(sourcePath(block, backendDir), 'utf8')));

/**
 * Replace everything between a block's markers with `generated`.
 *
 * Throws when a marker is missing rather than appending: a page without both
 * markers would silently grow a second copy of the table on every run.
 */
export function splice(target, marker, generated) {
  const begin = beginMarker(marker);
  const end = endMarker(marker);
  const start = target.indexOf(begin);
  const stop = target.indexOf(end);
  if (start === -1 || stop === -1 || stop < start) {
    throw new Error(`missing the ${begin} / ${end} markers`);
  }
  return target.slice(0, start + begin.length) + '\n\n' + generated + '\n\n' + target.slice(stop);
}

function main() {
  const backendDir = BACKEND_DIR;
  let failed = false;

  for (const block of BLOCKS) {
    const source = sourcePath(block, backendDir);
    if (!fs.existsSync(source)) {
      console.error(`✖ Nothing to sync at ${source}`);
      console.error(`  Regenerate it in the backend first (see the table at the top of this script).`);
      failed = true;
      continue;
    }

    const file = targetPath(block);
    const target = fs.readFileSync(file, 'utf8');
    let next;
    try {
      next = splice(target, block.marker, generatedBody(block, backendDir));
    } catch (error) {
      console.error(`✖ ${block.target} ${error.message}`);
      failed = true;
      continue;
    }

    if (next === target) {
      console.log(`✓ ${block.target} already up to date (${block.marker}).`);
    } else {
      fs.writeFileSync(file, next);
      console.log(`✓ ${block.target} synced from ${block.source}`);
    }
  }

  if (failed) process.exit(1);
}

// `node scripts/sync-backend-docs.mjs` runs the sync; importing it (the test) does not.
if (process.argv[1] && path.resolve(process.argv[1]) === fileURLToPath(import.meta.url)) {
  main();
}
